use crate::catalog_rows::{query_rows, text_at};
use oracle::Connection;
use relix_core::{ObjectKind, TableRef};
use relix_driver_api::DriverError;

const OBJECT_TYPES_SQL: &str = "SELECT object_type FROM all_objects \
     WHERE owner = :1 AND object_name = :2";

const DDL_SQL: &str = "SELECT DBMS_METADATA.GET_DDL(:1, :2, :3) FROM dual";

/// Returns the DDL generated by `DBMS_METADATA` (packages include their body). The
/// concrete catalog type is looked up first, because packages are listed as procedures.
pub fn object_definition(
    connection: &Connection,
    kind: ObjectKind,
    object: &TableRef,
) -> Result<Option<String>, DriverError> {
    let owner = object.schema.as_deref().unwrap_or_default();
    let name = object.name.as_str();
    let candidates = catalog_types(kind);
    let object_type = query_rows(connection, OBJECT_TYPES_SQL, &[&owner, &name])?
        .iter()
        .filter_map(|row| text_at(row, 0))
        .find(|object_type| candidates.contains(&object_type.as_str()));
    let Some(object_type) = object_type else {
        return Ok(None);
    };
    let metadata_type = object_type.replace(' ', "_");
    let rows = query_rows(connection, DDL_SQL, &[&metadata_type, &name, &owner])?;
    Ok(rows
        .first()
        .and_then(|row| text_at(row, 0))
        .map(|ddl| ddl.trim().to_owned()))
}

fn catalog_types(kind: ObjectKind) -> &'static [&'static str] {
    match kind {
        ObjectKind::Table => &["TABLE"],
        ObjectKind::View => &["VIEW"],
        ObjectKind::MaterializedView => &["MATERIALIZED VIEW"],
        ObjectKind::Sequence => &["SEQUENCE"],
        ObjectKind::Procedure => &["PROCEDURE", "PACKAGE"],
        ObjectKind::Function => &["FUNCTION"],
        ObjectKind::Trigger => &["TRIGGER"],
        ObjectKind::NodeLabel | ObjectKind::RelationshipType => &[],
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn packages_are_looked_up_with_procedures() {
        assert_eq!(
            catalog_types(ObjectKind::Procedure),
            ["PROCEDURE", "PACKAGE"]
        );
        assert_eq!(
            catalog_types(ObjectKind::MaterializedView),
            ["MATERIALIZED VIEW"]
        );
        assert!(catalog_types(ObjectKind::NodeLabel).is_empty());
    }
}
